      ]
    },
    {
      "evidence_id": "evidence-objectual-essence-route--d4e5f6a7b8c9",
      "title": "Objectual Essence Reduction",
      "excerpt": "Following Correia (2006, pp. 764-5) we account for objectual essence in terms of generic essence: FULL-OBJECTUAL-ESSENCE Being F is what x is in full iff: being F is what it is to be identical to x in full.",
      "overview": "This formal bridge extends the generic-identity treatment to claims about individual objects. It matters because the account is not limited to predicate essences: it also explains how an object’s essence can be treated through the generic condition of being identical to that object.",
      "evidence_type": "formal_argument",
      "claim_refs": [
